import base64


def encode_base64(data):
    return base64.b64encode(data).decode("ascii")


def decode_base64(text):
    return base64.b64decode(text)


def rot13(text):
    result = []
    for c in text:
        if "a" <= c <= "z":
            result.append(chr((ord(c) - ord("a") + 13) % 26 + ord("a")))
        elif "A" <= c <= "Z":
            result.append(chr((ord(c) - ord("A") + 13) % 26 + ord("A")))
        else:
            result.append(c)
    return "".join(result)


def simple_checksum(data):
    checksum = 0
    for byte in data:
        checksum ^= byte
    return checksum
